#### Phase 2: Create KMS Keys and Configure Access Policies

**Step 1: Create KMS Customer Master Keys**

```python
# scripts/create_kms_keys.py
import boto3
import json
import yaml

def create_kms_key_for_eaas(config: dict) -> str:
    """Create KMS key with proper policies for EaaS event encryption."""
    kms_client = boto3.client('kms')
    sts_client = boto3.client('sts')
    account_id = sts_client.get_caller_identity()['Account']

    # Build key policy
    key_policy = {
        "Version": "2012-10-17",
        "Statement": [
            {
                "Sid": "Enable IAM User Permissions",
                "Effect": "Allow",
                "Principal": {
                    "AWS": f"arn:aws:iam::{account_id}:root"
                },
                "Action": "kms:*",
                "Resource": "*"
            },
            {
                "Sid": "Allow publishers to generate data keys",
                "Effect": "Allow",
                "Principal": {
                    "AWS": config['publisher_roles']
                },
                "Action": [
                    "kms:GenerateDataKey",
                    "kms:GenerateDataKeyWithoutPlaintext"
                ],
                "Resource": "*",
                "Condition": {
                    "StringEquals": {
                        "kms:ViaService": [
                            f"kafka.{region}.amazonaws.com",
                            f"mq.{region}.amazonaws.com"
                        ]
                    }
                }
            },
            {
                "Sid": "Allow consumers to decrypt",
                "Effect": "Allow",
                "Principal": {
                    "AWS": config['consumer_roles']
                },
                "Action": "kms:Decrypt",
                "Resource": "*",
                "Condition": {
                    "StringEquals": {
                        "kms:ViaService": [
                            f"kafka.{region}.amazonaws.com",
                            f"mq.{region}.amazonaws.com"
                        ]
                    }
                }
            },
            {
                "Sid": "Allow CloudTrail to describe key",
                "Effect": "Allow",
                "Principal": {
                    "Service": "cloudtrail.amazonaws.com"
                },
                "Action": [
                    "kms:DescribeKey",
                    "kms:GetKeyPolicy"
                ],
                "Resource": "*"
            }
        ]
    }

    # Create multi-region key
    response = kms_client.create_key(
        Description=config['description'],
        KeyUsage='ENCRYPT_DECRYPT',
        Origin='AWS_KMS',
        MultiRegion=config.get('multi_region', False),
        Policy=json.dumps(key_policy),
        Tags=[
            {'TagKey': tag['Key'], 'TagValue': tag['Value']}
            for tag in config.get('tags', [])
        ]
    )

    key_id = response['KeyMetadata']['KeyId']
    print(f"Created KMS key: {key_id}")

    # Create alias
    kms_client.create_alias(
        AliasName=f"alias/{config['alias']}",
        TargetKeyId=key_id
    )
    print(f"Created alias: alias/{config['alias']}")

    # Enable automatic key rotation
    if config.get('automatic_rotation', True):
        kms_client.enable_key_rotation(KeyId=key_id)
        print(f"Enabled automatic key rotation for {key_id}")

    return key_id

# Load configuration
with open('config/kms-key-strategy.yaml', 'r') as f:
    strategy = yaml.safe_load(f)

# Create keys
for key_config in strategy['kms_keys']:
    key_id = create_kms_key_for_eaas(key_config)
    print(f"Successfully created key {key_config['alias']}: {key_id}\n")
```

**Step 2: Configure IAM Roles for Publishers and Consumers**

```bash
# Create IAM policy for event publishers
aws iam create-policy \
    --policy-name EaaSEventPublisherEncryptionPolicy \
    --policy-document file://iam/publisher-encryption-policy.json

# iam/publisher-encryption-policy.json
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowKMSGenerateDataKey",
      "Effect": "Allow",
      "Action": [
        "kms:GenerateDataKey",
        "kms:GenerateDataKeyWithoutPlaintext"
      ],
      "Resource": [
        "arn:aws:kms:us-east-1:123456789012:key/*"
      ],
      "Condition": {
        "StringEquals": {
          "kms:ResourceAliases": [
            "alias/gainwell-eaas-phi-encryption",
            "alias/gainwell-eaas-provider-encryption",
            "alias/gainwell-eaas-financial-encryption"
          ]
        }
      }
    }
  ]
}

# Create IAM policy for event consumers
aws iam create-policy \
    --policy-name EaaSEventConsumerDecryptionPolicy \
    --policy-document file://iam/consumer-decryption-policy.json

# iam/consumer-decryption-policy.json
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowKMSDecrypt",
      "Effect": "Allow",
      "Action": "kms:Decrypt",
      "Resource": [
        "arn:aws:kms:us-east-1:123456789012:key/*"
      ],
      "Condition": {
        "StringEquals": {
          "kms:ResourceAliases": [
            "alias/gainwell-eaas-phi-encryption"
          ]
        }
      }
    }
  ]
}

# Attach policies to roles
aws iam attach-role-policy \
    --role-name eaas-member-service \
    --policy-arn arn:aws:iam::123456789012:policy/EaaSEventPublisherEncryptionPolicy

aws iam attach-role-policy \
    --role-name eaas-eligibility-consumer \
    --policy-arn arn:aws:iam::123456789012:policy/EaaSEventConsumerDecryptionPolicy
```
